import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import poster from './Poster';
import Stars from './Stars';
import { read } from '../topStore';
import { topRated } from '../api';
import { t, formatTitle } from '../util';
const name = item => formatTitle(item.title, item.year, item.artist);

/**
 * The best-rated titles for a period. A reader of the shared top-rated store,
 * so it is safe to re-create on every redraw.
 */
export default class TopRatedList extends Component {
  view() {
    const {
      period = 'month',
      kind = '',
      limit = 10,
      compact
    } = this.attrs;
    const state = read({
      period,
      kind: kind || undefined,
      limit
    }, topRated, () => m.redraw());
    if (state.items === null) return m(LoadingIndicator, {
      display: "block"
    });
    if (!state.items.length) return m("p", {
      className: "ShelfTop-empty"
    }, t(state.failed ? 'top.failed' : `top.empty_${period}`));
    return m("ol", {
      className: compact ? 'ShelfTop ShelfTop--compact' : 'ShelfTop'
    }, state.items.map((item, index) => this.item(item, index, !!compact)));
  }
  item(item, index, compact) {
    return m("li", {
      className: "ShelfTop-item",
      key: item.id
    }, m("span", {
      className: "ShelfTop-rank"
    }, index + 1), poster({
      kind: item.kind,
      poster: item.poster,
      title: name(item),
      slug: item.discussionSlug,
      size: compact ? 'w92' : 'w185'
    }), m("div", {
      className: "ShelfTop-body"
    }, item.discussionSlug ? m("a", {
      className: "ShelfTop-title",
      href: app.route('discussion', {
        id: item.discussionSlug
      }),
      onclick: navigate
    }, name(item)) : m("span", {
      className: "ShelfTop-title"
    }, name(item)), m("span", {
      className: "ShelfTop-score"
    }, m(Stars, {
      value: Math.round(item.average * 2),
      size: "small"
    }), " ", m("b", null, item.average.toFixed(1)), ' ', m("small", null, t('card.ratings', {
      count: item.count,
      formatted: item.count
    }))), compact ? null : m("span", {
      className: "ShelfTop-kind"
    }, t(`kind.${item.kind}`))));
  }
}

/** Route in-app on a plain click; let modified clicks open a tab. */
function navigate(e) {
  if (e.ctrlKey || e.metaKey || e.shiftKey || e.button === 1) return;
  e.preventDefault();
  m.route.set(e.currentTarget.getAttribute('href'));
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/TopRatedList', TopRatedList);