import Model from 'flarum/common/Model';

/** A list's first four posters, kept on the list so cards cost nothing. */

export class Entry extends Model {
  rating() {
    return Model.attribute('rating').call(this);
  }
  status() {
    return Model.attribute('status').call(this);
  }
  owned() {
    return Model.attribute('owned').call(this);
  }
  doneOn() {
    return Model.attribute('doneOn').call(this);
  }
  ratedAt() {
    return Model.attribute('ratedAt', Model.transformDate).call(this);
  }
  updatedAt() {
    return Model.attribute('updatedAt', Model.transformDate).call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
  media() {
    return Model.hasOne('media').call(this);
  }
}
export class ShelfList extends Model {
  name() {
    return Model.attribute('name').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  itemCount() {
    return Model.attribute('itemCount').call(this);
  }
  preview() {
    return Model.attribute('preview').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  updatedAt() {
    return Model.attribute('updatedAt', Model.transformDate).call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
  media() {
    return Model.hasMany('media').call(this);
  }
}