import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import posterUrl from 'ext:ernestdefoe/marquee/forum/utils/posterUrl';
/**
 * A title's poster, linking to the busiest discussion about it the viewer can
 * see (or to nothing). Square for albums, portrait for everything else.
 */
export default function poster({
  kind,
  poster,
  title,
  slug,
  size = 'w185'
}) {
  const img = poster ? m("img", {
    src: posterUrl(poster, size),
    alt: "",
    loading: "lazy",
    decoding: "async"
  }) : m("span", {
    className: "ShelfPoster-blank",
    "aria-hidden": "true"
  });
  const className = `ShelfPoster ShelfPoster--${kind}`;
  return slug ? m(Link, {
    className: className,
    href: app.route('discussion', {
      id: slug
    }),
    "aria-label": title
  }, img) : m("span", {
    className: className
  }, img);
}

/** A title's poster from the store's model. */
export function mediaPoster(media, title) {
  return poster({
    kind: media.kind(),
    poster: media.poster(),
    title,
    slug: media.attribute('shelfSlug')
  });
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/Poster', poster);